quests[31651] = { id = 31651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Monastery Challenge Mode - Gold Addition (Nth)" }
quests[31656] = { id = 31656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threat in the South", description = "With the Sha of Hatred dead, the greatest threat to this land is vanquished, but our travels along the southern border have made it exceedingly clear that the mantid forces in the Dread Wastes are on the move, and likely won't be held back for long.\n\nIf you wish to continue to aid the Shado-Pan, I would recommend reporting in to Bowmistress Li on the Serpent's Spine. She oversees the great wall that separates the terrors in the Dread Wastes from our bountiful lands to the east.", sourceObjective = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31660] = { id = 31660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Fit to Swarm", description = "Newly hatched mantid have only two instincts: kill and feed. They turn on one another, devouring the weak and leaving the strongest to mature.\n\nThose hatched during a swarm - the swarmborn - are turned loose on our enemies instead.\n\nThe swarmborn in the Clutches of Shek'zeer have been tainted. They are born into shadows and nightmares. Driven by terror, not hunger.\n\nThey are not fit to swarm. They must be purged.", sourceObjective = "Slay 30 Shek'zeer Swarmborn in the Clutches of Shek'zeer.", completion = "Their eggs should have basked in the warmth of the sun and the song of a million wings for ten more years.\n\nThe Empress will pay for her crimes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31661] = { id = 31661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Source of Terrifying Power", description = "<The clutch-keepers seem to be using these blinding white crystals as magical foci. Peering inside, you see thick tendrils of black smoke swirling in the center. One of the workers at Klaxxi'vess may know more about this material and why it is so abundant in the wastes.>", sourceObjective = "Bring the Sha-Haunted Crystal to Ambersmith Zikk at Klaxxi'vess.\n\nProvided item:", completion = "Do you have any idea what this is? It's amber!\n\nBut it is polluted with fear.\n\nI would not expect an outsider like you to understand the consequences of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[31664] = { id = 31664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Anglers Quest", description = "This journal provides a hazy recollection of Nat Pagle's grand adventures.  Simply reading it will undoubtedly provide a useful insight into fishing.", sourceObjective = "Read Nat's Fishing Journal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31669] = { id = 31669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cabbage Test", description = "Grandpa always said that the bellweather of a true farmer lies in the quality of his cabbage. Any time a new farmer came into town, he'd buy a few heads of cabbage to see what they knew.\n\nNow, I'm the new farmer, and this is my big chance to prove myself. Could you plant some cabbage for me?", sourceObjective = "Plant a Green Cabbage in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Good farmers grow good cabbage. Bad farmers, bad cabbage. Pretty simple.", completion = "Wait until they try these cabbages. Then they'll know I'm the real deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[31670] = { id = 31670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Dangling Carrot", description = "Grandpa always said, \"Carrots ain't nothin but a welcomin' mat for virmen.\" I don't think I ever saw him grow a single carrot.\n\nFor once, I disagree with Grandpa. I like to live on the edge. Plus, I like to eat carrots.\n\nI like to eat carrots on the edge.\n\nCould you get some seeds and grow one for me?", sourceObjective = "Plant a Juicycrunch Carrot in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "I ain't afraid of no virmen.", completion = "I can't wait to get my paws on those carrots. Thank you, {name}. See you again tomorrow?", sourceObjectiveStatus = "unverified-source-field" }
quests[31671] = { id = 31671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why Not Scallions?", description = "I heard Haohan mentioning that he was going to plant scallions today. I'm not sure if today's the best day for scallions, but I'd like to hope that he knows what he's doing. He is the head of the Tillers' union, after all.\n\nCould you plant a scallion for me?", sourceObjective = "Plant a Scallion in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "What do you mean, I have dirt on my nose? What's that supposed to mean, {name}? Are you calling me a brown-noser?\n\nOh, I see. I DID have a little bit of dirt on my nose. Thank you for the helpful tip.", completion = "I can already smell those scallions from over here. Can't wait to pick 'em and sell 'em tomorrow. Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[31672] = { id = 31672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pumpkin-y Perfume", description = "I heard a rumor around the market that Gina Mudclaw loves the smell of pumpkin blossoms. Maybe if I grow some pumpkins in my farm, she might come and visit a little more often.\n\nCould you plant a pumpkin for me?", sourceObjective = "Plant a Mogu Pumpkin in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Did you plant the pumpkin yet?", completion = "And now, we play the waiting game...\n\nSorry, that sounded a little creepy. Forget I said that.", sourceObjectiveStatus = "unverified-source-field" }
quests[31673] = { id = 31673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Blossom Leeks, You Make the Croc-in' World Go Down", description = "Grandpa once told me that the smell of leeks will keep crocolisks off of your property. He must have had a point... he always grew leeks, and I never saw a crocolisk anywhere NEAR his farm.\n\nWe're pretty far from the water... but I suppose you can never be too sure.", sourceObjective = "Plant a Red Blossom Leek in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Come to think of it, Grandpa didn't live near the water either...", completion = "I'd like to see any crocolisks attack my farm now!\n\nHa HA!", sourceObjectiveStatus = "unverified-source-field" }
quests[31674] = { id = 31674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pink Turnip Challenge", description = "Old Hillpaw bet me that my land couldn't grow a pink turnip.\n\nI'll show him. My land will grow the biggest, pinkest turnip that old coot's ever seen!", sourceObjective = "Plant a Pink Turnip in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Old Hillpaw... what a maroon.", completion = "Hah! That'll show Hillpaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[31675] = { id = 31675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The White Turnip Treatment", description = "Grandpa often told me to \"Keep my drawers clean and my dirt cleaner.\" It sounds like a joke, but he makes a good point.\n\nVegetables tend to leave behind bits of root that can contaminate your soil... but a nice, big, white turnip will clean that gunk right up. Think you could plant a white turnip for me?", sourceObjective = "Plant a White Turnip in Sunsong Ranch. You can purchase seeds from Merchant Greenfield in the Halfhill Market.", progress = "Now keepin' your drawers clean, that's more of a personal thing. Grandpa made a good point there, too.", completion = "Look at that dirt. Practically sparkling.\n\nGrandpa would be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[31676] = { id = 31676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Vengeance", description = "I can hear them howling in rage... The spirits of the Gurthani mogu I slayed so long ago. They wander this ruined terrace, seeking vengeance.\n\nIf they find me in this state, I will not have the strength to fend them off. Draw their attention and put them down.\n\nFinish what I started, and I will tell you who I am.", sourceObjective = "Slay 6 Vengeful Gurthani Spirits in the Terrace of Gurthan.", progress = "The mogu of Clan Gurthan are quilen lords. Do not wake their guardians.", completion = "We have a common enemy in the mogu. And perhaps others.\n\nWe shall see.", sourceObjectiveStatus = "unverified-source-field" }
quests[31677] = { id = 31677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Ashes", description = "<Kil'ruk the Wind-Reaver defeated Warlord Gurthan centuries ago, but the mogu beastmaster's spirit continues to haunt the ruins of his old stronghold.\n\nShowing proof of your victory over this spirit may gain you favor in the eyes of the Klaxxi.>", sourceObjective = "Bring the Ashes of Warlord Gurthan to Kil'ruk the Wind-Reaver at Klaxxi'vess.\n\nProvided item:", completion = "Gurthan was a coward who trained beasts to do the fighting for him and, in the face of death, chose to suspend his spirit in that urn.\n\nNow we can have the pleasure of killing him as many times as we like.\n\nWell done.", sourceObjectiveStatus = "unverified-source-field" }
quests[31679] = { id = 31679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", sourceObjective = "Activate the Resonating Beacon in Amberglow Hollow.", sourceObjectiveStatus = "unverified-source-field" }
quests[31680] = { id = 31680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", sourceObjective = "Kill 8 Amber Harvesters on the Stinging Trail.", completion = "The Klaxxi are pleased with our work, outsider. You have proven to be more resourceful than we thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[31681] = { id = 31681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", sourceObjective = "Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail.", progress = "I would go with you to gather amber, but my talents are more useful here.", completion = "Even this raw amber will be of use. We can't afford to be picky in times like these.\n\nThe Klaxxi'va will be glad I thought of this. I will tell them you helped!", sourceObjectiveStatus = "unverified-source-field" }
quests[31682] = { id = 31682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaley hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this the Klaxxi will be pleased with us.", sourceObjective = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", completion = "What... what sort of creature are you?\n\nHow have you awoken me?", sourceObjectiveStatus = "unverified-source-field" }
quests[31685] = { id = 31685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of the Four Winds", description = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin.  Talk with me when ye be ready to go and I can give ye a ride ta where ya need to go.  Talk to me cohort on the other side 'ta get some equipment to aid ya on yer journey.", sourceObjective = "Teleport to Valley of the Four Winds and speak to Private Tim P. O'Rary.", sourceObjectiveStatus = "unverified-source-field" }
quests[31687] = { id = 31687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Sik'thik", description = "For all our efforts to keep the mantid in the Dread Wastes, some have broken through, seemingly intent on Niuzao Temple. My men have been attempting to extinguish their presence to the west, at Sik'vess, but to no success. If you're half of the {class} Taran paints you to be, maybe you will fare better.\n\nHead west, and kill any Sik'thik mantid you find. And remember, this is no time for mercy. There are lives at the temple depending on us.", sourceObjective = "Kill 12 Sik'thik mantid.", completion = "The mantid are relentless. Fortunately for us, you have a dedication that surpasses even theirs.\n\nIt is good to have you walk these roads, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31688] = { id = 31688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Restless Leng", description = "One of my best scouts, Restless Leng, went missing during a mission on the other side of Sik'vess. I'm hopeful that he was captured rather than killed, but with the mantid corrupted so heavily by sha, it doesn't seem likely.\n\nStill, can you investigate the cages around Sik'vess? I owe him a more thorough search than even this, but I have no men to spare without allowing our southern lines to break.\n\nPlease, {class}, even if there's no life left in him, find him that I might know his fate.", sourceObjective = "Search Sik'thik Cages for Restless Leng.", completion = "Leng told me of your heroics. He is in your debt, as am I.", sourceObjectiveStatus = "unverified-source-field" }
quests[31689] = { id = 31689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadsworn", description = "The Klaxxi see far and hear much. They have shared their insight with me.\n\nThe Vor'thik embrace the sha, using its power to fuel their march in this false swarm. Their warriors consume tainted amber and call themselves dreadsworn.\n\nThere is no future for them. They are waste which needs disposing.\n\nAnd YOU will begin that process for us when you reach Kypari Vor.", sourceObjective = "Slay 6 Vor'thik Dreadsworn at Kypari Vor.", completion = "In disciplined hands, the spear is the perfect weapon. Only the weak would augment it with sorcery.\n\nAnd we have no need for the weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[31690] = { id = 31690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscribed Tiger Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", sourceObjective = "Bring your Inscribed Tiger Staff to Inkmaster Glenzu in the Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31691] = { id = 31691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscribed Crane Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", sourceObjective = "Bring your Inscribed Crane Staff to Inkmaster Jo Po in the Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31692] = { id = 31692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscribed Serpent Staff", description = "As powerful it is, at some point you know you will outgrow this staff.  When that time comes, one of the Inkmasters in the Arboretum would most likely be interested in taking it from you.", sourceObjective = "Bring your Inscribed Serpent Staff to Inkmaster Wei in the Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[31693] = { id = 31693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julia Stevens", description = "Think you can take me again?", sourceObjective = "Defeat Julia Stevens in a pet battle.", completion = "Ouch, you really are a good pet trainer! I guess you're the exception.", sourceObjectiveStatus = "unverified-source-field" }
quests[31694] = { id = 31694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hisingen Blues" }
quests[31695] = { id = 31695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beyond the Wall", description = "We received word the Shado-Pan have begun a counter attack in to Townlong Steppes. It sounds like they are going after the root of the yaungol invasion.\n\nThe pandaren have not traveled in force in to Townlong for thousands of years. The Shado-Pan are strong and brave, but they are also proud and few. They will need help from heroes like yourself. Can you travel through the Gate of Winter's Blossom in the northwest? Find the Shado-Pan leaders and lend your help and experience?", sourceObjective = "Speak with Taran Zhu at the Longying Outpost in Townlong Steppes.", completion = "Welcome to Townlong Steppes. If you insist on wandering in to the darkest places of Pandaria then far be it from me to not put you to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[31697] = { id = 31697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ACCIDENTAL COPY [reuse if you like]", description = "The mantid numbers have been increasing since you left for the cleft. Let's put these orbs you gathered to use.\n\nGet down on the battlefront and man one of the cannons. Let none through.", sourceObjective = "Use a Dragon Launcher to kill 50 swarming mantid.", sourceObjectiveStatus = "unverified-source-field" }
quests[31698] = { id = 31698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning The Pack", description = "The past few seasons have been plentiful, and as a result, the wild tiger population on Windward Isle has exploded.\n\nThe savage creatures have hunted out all the nearby game, and are beginning to encroach upon the cloud serpent nests.\n\nAs a result, as the tigers thrive, the cloud serpents decline.\n\nIf we are not careful, the predatory cats could completely wipe them out.\n\nWe must thin the tigers' numbers, {race}.", sourceObjective = "Kill 8 Windward Tigers or Windward Alphas.", completion = "You have carried out the task to the letter, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31699] = { id = 31699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprite Fright", description = "Oh bother, how am I supposed to get my tasks done, now?\n\nInstructor Skythorn asked me to go kill some tigers at Windward Isle, but I heard the area was overrun with sprites!\n\nUgh! I hate sprites! They totally give me the creeps!\n\nThey're so small, and... and... they jump on you and... and... they have cold, dead little stick hands!\n\nAuuugh! You have to help me, {name}. Get rid of those things, please!", sourceObjective = "Kill 7 Shadowfae Tricksters.", progress = "So I don't like sprites. What's the big deal?", completion = "You have put the sprites in their place, {name}. They should cause no more trouble for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[31700] = { id = 31700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shoe Is On The Other Foot", description = "I loathe sprites! One time, one of those nasty buggers followed me all day, putting dirt in my tea and bugs in my hair.\n\nI mean, who does that!?\n\nWell, I think it's time for a little payback. Do you know what the sprites up at Windward Isle love more than anything in the world?\n\nYeah, you guessed it. Shoes!\n\nAnd we're going to steal them. Won't that make them mad! Hah!\n\nWell, I'm scared to go near sprites, so you'll have to do it, {name}.", sourceObjective = "Re-steal 14 Stolen Boots.", progress = "Did you see the looks on their faces? Were they mad?", completion = "I see you and Ningna have been up to some mischief. Unfortunately, this type of behavior is not condoned by the Order--\n\nWait, where did you find those shoes? I've been looking for that pair of moleskin riding boots for ages!\n\nWell... I suppose I will let this slide... this time. Hmph.", sourceObjectiveStatus = "unverified-source-field" }
quests[31701] = { id = 31701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Huntress", description = "I have learned that a vicious beast, a Windward Huntress, terrorizes the wood on the northwest side of the island.\n\nShe has already slain several serpents, and injured more than one serpent rider sent to subdue her.\n\nShe must be removed before she can pose a danger to anyone else. Can you perform this task?", sourceObjective = "Kill the Windward Huntress.", completion = "Thank you, {name}. You are proving to be quite a reliable student.", sourceObjectiveStatus = "unverified-source-field" }
quests[31702] = { id = 31702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Prowl", description = "I have heard report of a great white beast that stalks the wood on the northwestern side of the wild serpent island.\n\nThis savage creature is mate to the Windward Huntress, and already he has taken down several of the adult cloud serpent matriarchs.\n\nWe cannot have such a fearsome predator roaming the island unchecked.\n\nGo and deal with this creature. Let us see if your training has paid off.", sourceObjective = "Kill the Windward Saber.", completion = "I see you have vanquished the beast. Quite a promising student, you are.", sourceObjectiveStatus = "unverified-source-field" }
quests[31703] = { id = 31703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Madcap Mayhem", description = "There is another task I must ask of you.\n\nThe leader of the woodland sprites is the Shadowfae Madcap.\n\nIf there is trouble brewing, he is the mastermind pulling the puppet strings.\n\nWe do not have time to deal with the sprites' tiresome pranks and insolence. Take out the Shadowfae Madcap, and be quick about it.", sourceObjective = "Kill the Shadowfae Madcap.", completion = "Good riddance. With everything that is worrying us these days, it is good to have one less problem to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[31704] = { id = 31704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pooped", description = "<Your serpent catches your gaze and ducks its head bashfully.>\n\nYou can tell that someone has gotten out of its pen and had \"an accident.\"\n\nWell, at the rate that the hatchling's been eating, it had to come out the other end... somewhere.\n\nYou had better find the serpent's poop and clean it up before the Serpent Masters find out.", sourceObjective = "Collect 5 Tiny Bags of Poop.", progress = "<The hatchling watches you innocently.>", completion = "The hatchling plays contentedly, oblivious to your efforts. Sigh... sometimes, the life of a serpent trainer is quite thankless.", sourceObjectiveStatus = "unverified-source-field" }
quests[31705] = { id = 31705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Needle Me Not", description = "The Arboretum is our home, a safe haven where we raise young hatchlings and train our students.\n\nUnfortunately, there are other, more dangerous creatures who wish to make this their home as well.\n\nTo the north, beyond the river, we have seen a great wasp feeding on the nectar blossoms.\n\nThis creature has already stung several of our students.\n\nUse this honey to lure the wasp out of hiding. Then, destroy it before it harms anyone else.", sourceObjective = "Use the honey at the northern clearing in The Arboretum, and then kill the Orchard Needler.", progress = "The nectar attracts many unsavory creatures.", completion = "The poisonous wasp is dead? Good. Where so many other students failed, you have succeeded, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31706] = { id = 31706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeping Widows", description = "The spiders near Sri-La Village have grown very aggressive. They pose a severe problem to the anglers who fish along the coast.\n\nFor their safety, I need you to go and eliminate the Weeping Widows in The Widow's Wail.\n\nYou can find the cave along the coast to the north.", sourceObjective = "Kill 7 Weeping Widows.", completion = "Instructor Skythorn updated me on the situation at The Widow's Wail. You have done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[31707] = { id = 31707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tangled Web", description = "We have had a disturbing report from the Anglers fishermen of Sri-La Village, {name}.\n\nMany of their villagers are missing, taken by the spiders who live in The Widow's Wail, a cave along the coast to the north.\n\nThe victims are dragged into the dark depths, wrapped in cocoons, and left to become the spiders' next meal.\n\nWe believe that some of the people may still be alive. There is still time to save them! I need you to go and rescue as many villagers as you can find.", sourceObjective = "Destroy Widow's Webs to free 5 Sri-La Villagers.", completion = "You have done a great deed today, {name}. This is the duty of the Order of the Cloud Serpent - to protect the people of The Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[31708] = { id = 31708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpent's Scale", description = "I see you have gained your own hatchling, {race}.\n\nHave you been feeding it, cleaning after it, and playing with it properly? Only by doing so will it become strong and healthy.\n\nNow let me tell you a trainer's secret. To the north, in The Widow's Wail, you can find a mushroom known as Serpent's Scale.\n\nIt is difficult to acquire, but this mushroom has powerful properties and important nutrients. Your serpent won't like eating it, but who likes eating their vegetables?", sourceObjective = "Collect 25 Serpent's Scale.", progress = "<Your serpent greets you happily.>", completion = "<Your serpent sniffs the mushrooms and makes a horrible face. It tries to escape, but you hold it gently and coax it to eat the spongy morsels.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31709] = { id = 31709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Doubt", description = "I heard that there has been some strange behavior down at The Widow's Wail to the north.\n\nHyacinth and I went to investigate, and I am certain that some presence of the sha has found its way into the cavern.\n\nI created this device to measure sha energy levels.\n\nIf you are going that way, would you mind taking measurements of any sha disturbances?\n\nThe disturbances look like streams of white and black sha energy pouring from the ground.", sourceObjective = "Use the Sha Attunement Device at the Sha Disturbances in The Widow's Wail. The entrance to The Widow's Wail can be found to the north along the coast, south of Sri-La Village.", completion = "Thank you for bringing me this report, {name}. Big Bao is quite right to be concerned.\n\nThe sha is a subtle and deadly enemy. We must work to expel their dark energy from this land.", sourceObjectiveStatus = "unverified-source-field" }
quests[31710] = { id = 31710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiny Treats", description = "As you near, your serpent opens its mouth and begins drooling. It looks quite hungry since you last left it.\n\nFrom the way it whimpers and slaps its tail, you can tell it is not looking for just any treat, but a special favorite snack.\n\nYour serpent loves to munch on tiny spider eyes, but this delicacy comes only from the Widowspawn spiders in the cave along the coast to the north.\n\nWell, what's a rider to do? Your serpent is waiting.", sourceObjective = "Collect 100 Tiny Spider Eyes.", progress = "Your serpent perks up at your return.", completion = "Your serpent nudges your hand affectionately, then proceeds to devour the treats!", sourceObjectiveStatus = "unverified-source-field" }
quests[31711] = { id = 31711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seed of Doubt", description = "The problem with the sha of doubt, {race}, is its deceitful pervasiveness.\n\nOnce the seed of doubt is planted, it can grow like an unwelcome weed.\n\nSuch a seed has been planted in The Widow's Wail to the north, and like a weed, we must extinguish its presence immediately.\n\nI need you to destroy the lingering fragment of doubt before it can infect any more victims.", sourceObjective = "Kill the Seed of Doubt.", progress = "Doubt is a difficult enemy to vanquish because in a sense, we are fighting ourselves. Stand tall and be confident in your own actions, {name}.", completion = "Excellent work, {name}. I \"doubt\" that this enemy is truly gone. Until we can be sure, we must stay vigilant.", sourceObjectiveStatus = "unverified-source-field" }
quests[31712] = { id = 31712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monkey Mischief", description = "Strange tales have reached our ears from Sri-La Village.\n\nIt seems that a hozen tribe has made itself comfortable in Oona Kagu, a cave along the coast south of the fishing village.\n\nToo comfortable, in fact. The tribe members are stealing and pillaging resources all along the coast.\n\nWe must teach them a lesson... one that can only be taught by force. They have already overstayed their welcome.", sourceObjective = "Kill 13 Oona hozen.", progress = "We serve the people of The Jade Forest. We will ensure their protection and well-being.", completion = "The hozen presence is quite troubling. You did well to follow Instructor Skythorn's instructions.", sourceObjectiveStatus = "unverified-source-field" }
quests[31713] = { id = 31713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Brew-haha", description = "It's a disaster, {name}!\n\nWhen I went to visit the Dancing Serpent Inn yesterday, they were all out of brew. They said the shipment from Sri-La Village had been stolen. STOLEN!\n\nTurns out those Oona hozen have been making all kinds of trouble down at the docks, including taking all the brew to their cave at Oona Kagu along the coast.\n\nI can't handle a dry spell. A life without brew is not a life worth living!\n\nSomeone needs to go and save the brew!", sourceObjective = "Collect 100 Sri-La Stout.", progress = "Is the brew recovered yet? I'm... I'm starting to lose it...", completion = "Oh, thank the Stormstouts! You are my hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[31714] = { id = 31714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Serpents", description = "Those Oona hozen have gone too far this time.\n\nDo you know what they are doing with wild cloud serpents? Captured hatchlings are forced to fight one another in the pits, for nothing more than the Oona's amusement.\n\nSavages!\n\nIf the young hatchlings learn such aggressive behavior at a young age, they may become violent and corrupted adults. A malicious cloud serpent is not something we want to deal with.\n\nWe must save the hatchlings.", sourceObjective = "Collect 10 Rescued Serpents.", progress = "The Order of the Cloud Serpent has worked for centuries to make the cloud serpents into loyal companions. Our kindness brings out the best in these creatures.\n\nUnfortunately, violence and anger can quickly turn them into destructive monsters.", completion = "Ah yes, these hatchlings look quite tired. They have been through a great ordeal, but thanks to you, they are safe now.", sourceObjectiveStatus = "unverified-source-field" }
quests[31715] = { id = 31715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Kah-Oona", description = "The leader of the Oona hozen is a brigand by the name of Lord Oona.\n\nI have heard fearsome tales of this roaming sea captain and his crew. Everywhere he takes his tribe, destruction follows.\n\nThe Oona land their boats on fertile soil, pillage the local villages, and drain the land dry before moving on to their next conquest.\n\nWe shall not allow the same to occur on our shores, not while I am still in charge.\n\nI need someone to go eradicate him now.", sourceObjective = "Kill Lord Oona.", completion = "The leader is dead, then? Good. Perhaps now the hozen will leave the villagers in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[31716] = { id = 31716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pooped", description = "<As you approach the pen, the serpent zips into a corner and hides.>\n\nAs it looks at you with bashful eyes, you can tell that someone has gotten out of its pen and had... an accident.\n\nWell, at the rate that the serpent's been eating, it had to come out the other end... somewhere.\n\nYou had better find the serpent's poop and clean it up before the Serpent Masters find out.", sourceObjective = "Collect 5 Big Bags of Poop.", progress = "<The serpent watches you in amusement.>", completion = "The cloud serpent plays contentedly, oblivious to your efforts. Sigh... sometimes, the life of a serpent trainer is quite thankless.", sourceObjectiveStatus = "unverified-source-field" }
quests[31717] = { id = 31717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trainer's Challenge: Ace Longpaw", description = "You are rising up the ranks of our students, {name}.\n\nJust as a sword must be forged through fire, so must our students test themselves against one another.\n\nToday, you will spar against one of our brightest disciples, Ace Longpaw. In order to defeat him, you will need to make use of your defensive capabilities.\n\nSpeak to him in the training ring to begin the challenge. Good luck.", sourceObjective = "Speak to Ace Longpaw, then defeat him.", progress = "How did the challenge go?", completion = "Well done, {class}. The sword that is hammered and folded produces a keen blade.", sourceObjectiveStatus = "unverified-source-field" }
quests[31718] = { id = 31718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trainer's Challenge: Big Bao", description = "Are you ready for another lesson, {name}?\n\nToday, you will spar against Big Bao. He is large of stature and of heart, and he will not give up until he is wholly beaten.\n\nIf you wish to defeat him, you will need to persevere.\n\nSpeak to him in the training ring to begin the challenge. Good luck.", sourceObjective = "Speak to Big Bao, then defeat him.", progress = "How did the challenge go?", completion = "Both of you persevered to the end. Well done, my student.", sourceObjectiveStatus = "unverified-source-field" }
quests[31719] = { id = 31719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trainer's Challenge: Ningna Darkwheel", description = "You show much promise, {name}. However, talent is worth little without discipline and humility.\n\nToday, you will face Ningna Darkwheel. Her natural strength makes her one of our most talented students. \n\nIf you hope to defeat her, you will need to act with the utmost control.\n\nSpeak to her in the training ring to begin the challenge. Good luck.", sourceObjective = "Speak to Ningna Darkwheel, then defeat her.", completion = "A fight against Ningna will quickly reveal one's strengths and weaknesses. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[31720] = { id = 31720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trainer's Challenge: Suchi the Sweet", description = "Today you will face Suchi the Sweet in the training ring. Despite her sweet exterior, she is a tough opponent.\n\nShe attacks swiftly and surely, but such potent attacks can become tiring over time.\n\nIf you hope to defeat her, you will need to concentrate your damage when she is weakened.\n\nSpeak to Suchi to begin the duel. Good luck.", sourceObjective = "Speak to Suchi the Sweet, then defeat her.", sourceObjectiveStatus = "unverified-source-field" }
quests[31721] = { id = 31721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trainer's Challenge: Qua-Ro Whitebrow", description = "Qua-Ro Whitebrow is commonly considered the best student of the Order.\n\nHe seems quite without weakness. He is quick of intellect, strong of arm, hard-working, and talented.\n\nWhen you face him in the training ring, you will be testing yourself against our best.\n\nSpeak to him to begin the duel. No matter the outcome, you will learn much from challenging him.", sourceObjective = "Speak to Qua-Ro Whitebrow, then defeat him.", completion = "Your skills are remarkable, {name}. When I see such promising students as yourself, I know that The Order will pass into good hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[31723] = { id = 31723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of the Four Winds", description = "Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin.  I can help ye on yer way if ye wants to explore it.  Be sure to check out me wares for some equipment that may help ye on yer journey.", sourceObjective = "Speak to Private Tim P. O'Rary in the Valley of the Four Winds.", sourceObjectiveStatus = "unverified-source-field" }
quests[31725] = { id = 31725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay", description = "Are you ready to show off what you can do? There's a little girl up in Redridge Mountains that has made a real storm on the battle scene.\n\nFind Lindsay at the dock at Camp Everstill. She may be young, but her impressive record is nothing to be scoffed at!", sourceObjective = "Defeat Lindsay in a pet battle.", progress = "Who taught you how to fight, mister?", completion = "You're mean! Why didn't you let me win? Everyone always lets me win!", sourceObjectiveStatus = "unverified-source-field" }
quests[31726] = { id = 31726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric Davidson", description = "I heard all my friends talking about a scary worgen called Eric Davidson in Duskwood that nobody ever fights with their pets.\n\nI bet if you found and beat him, people might talk about you instead!", sourceObjective = "Defeat Eric Davidson in a pet battle.", completion = "Not only do you not fear me or my home, you have defeated me honorably. I'm impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[31727] = { id = 31727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gambling Problem", description = "If this war is to be won we cannot afford to leave anything unchecked, outsider.\n\nThere is a disturbance along the coast that needs to be investigated. The presence there is not our kind and are of no value to us. However, their supplies could prove very valuable.\n\nIf there is anything of use there we must get to it before the empress.", sourceObjective = "Speak with Deck Boss Arie at Soggy's Gamble in Dread Wastes.", completion = "So the bugs have taken an interest in us have they? Well if they want somethin' from us they'll have to come and earn it themselves!\n\nYou work for what you get here. That means you too!", sourceObjectiveStatus = "unverified-source-field" }
quests[31728] = { id = 31728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bill Buckler", description = "My longtime friend, fellow trainer, and infamous drunkard Bill Buckler of the Cape of Stranglethorn, has issued an open challenge to prepared trainers!\n\nYou should answer his call and really put your skills to the test. He tends to wander the southern roads of the Cape.", sourceObjective = "Defeat Bill the Pirate in a pet battle.", progress = "You aren't sho tough ...hic!", completion = "I demand a do-over ...hic! That washn't fair! There was two of ye!", sourceObjectiveStatus = "unverified-source-field" }
quests[31729] = { id = 31729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steven Lisbane", description = "If you thought I was tough, prepare yourself. The road only gets harder from here.\n\nFind Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", sourceObjective = "Defeat Steven Lisbane in a pet battle.", progress = "Where did you acquire such an intriguing team?", completion = "What a show! A most excellent skirmish indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[31730] = { id = 31730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Not So Friendly Request", description = "Scouts have reported a non-mantid presence near Kor'vess. Their intrusion and their theft of amber would normally be dealt with swiftly, but our forces are needed elsewhere.\n\nThis task seems suited to you, Wakener. You will convince them to leave this land, or you will destroy them in the name of the Klaxxi'va.", sourceObjective = "Speak with Sapmaster Vu at The Brewgarden in Dread Wastes.", completion = "So they want us to leave do they? What a selfish request! We're only taking amber from one tree.\n\nWell, I'm not going anywhere! I have brew to make.\n\nIf you help us maybe we can all come to a mutually beneficial agreement. I give them some brew, they stop trying to kill us.", sourceObjectiveStatus = "unverified-source-field" }
quests[31732] = { id = 31732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash Hell", description = "I will NOT let the Horde gain a foothold on these shores before we do! If you're looking to jump into the fray, I've got a spare gyrocopter for you at the end of the runway. An attack run is already programmed in, all you have to do is concentrate on shooting.\n\nUnleash hell upon these orcs!", sourceObjective = "Use a Skyfire Gyrocopter to slay 60 of the Garrosh'ar troops and destroy 8 Garrosh'ar Shredders, and then sink the Bladefist Reaper and Stygian Scar.", progress = "What are you waiting for?! Scorch the ground beneath them!", completion = "A proper welcome for the Horde to this new land!", sourceObjectiveStatus = "unverified-source-field" }
quests[31733] = { id = 31733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touching Ground", description = "Their town is burning and their men are scattered and broken. I need every available man on the ground NOW to finish them off.\n\nGrab one of the parachutes on the edge of the ship and get down there!", sourceObjective = "Use a Skyfire Parachute to touch ground in Garrosh'ar Point, then speak to Sully \"The Pickle\" McLeary.", progress = "Move it!", completion = "'Bout time you showed up, laddy! Let's do some damage!", sourceObjectiveStatus = "unverified-source-field" }
quests[31734] = { id = 31734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome Wagons", description = "Did you see the size of those war wagons? They're packing so many explosives, I cannae tell if the Horde is here to take over this continent or just blow it out of the sea!\n\nWe need to neutralize those wagons before they leave Garrosh'ar Point.\n\nHere, take me pocket flares. Fire 'em into a wagon and watch the fireworks!", sourceObjective = "Use Sully's Flaregun to destroy 5 Horde War Wagons.", progress = "Did \"The Pickle\" send you with a mission?", completion = "With those wagons out of commission, we can turn our attention to the commander.", sourceObjectiveStatus = "unverified-source-field" }
quests[31735] = { id = 31735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Tool For The Job", description = "I've scouted the area and found no leads on the prince or Admiral Taylor. We need to neutralize this base quickly and continue our search elsewhere.\n\nOperations here are being led by an orc warlock; Ga'trul. He's barricaded the dock and is trying to escape through a demonic circle.\n\nPut that flaregun to work again and blow those barricades! I'll cover your back and move in when you reach Ga'trul.", sourceObjective = "Use Sully's Flaregun to clear out the barricades and confront Ga'trul at the end of the dock.", progress = "We will complete our mission, but right now our priority is that {class}!", completion = "We'll catch up with him again. I'm sure of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[31736] = { id = 31736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy of the Alliance", description = "North of this base is a cherry blossom orchard and a village tucked away behind it. We will need to quarter there and tend to our wounded while we plan our next move.\n\nHead to that village and make contact with the native leader. Agent Mishka and I will rendezvous with you there.\n\nBe courteous, {name}! I am authorizing you to represent the entire Alliance here.\n\nI'm banking that seeing a powerful Alliance hero like you should make a favorable impression.", sourceObjective = "Find and meet with the leader of Paw'don Village.", completion = "When the mist fell, we knew it would only be a matter of time before visitors arrived.\n\nWe could not have predicted it would be like this.", sourceObjectiveStatus = "unverified-source-field" }
quests[31737] = { id = 31737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of War", description = "This whole place is going up in flames and the Skyfire is reporting that more of those... shadows are crawling up out of the ground. We need to get our people out of here.\n\nClear a path through the base on your way north and head for the town. I will rendezvous with you there.", sourceObjective = "Slay 15 Sha Haunts and 5 Sha Harbingers in Garrosh'ar Point.", progress = "You have no idea what kind of consequences your actions may have here!", completion = "I am glad you took responsibility for your actions. Left unchecked, negative emotions can quickly overwhelm an individual here, just as they started to overwhelm the one you call \"Rell.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[31738] = { id = 31738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pillaging Peons", description = "How did my village become a battlefield?\n\nTo the west, your Horde enemies cut down our precious orchard. Without our apple trees, we will have no harvest, no food, and no livelihood.\n\nIf you are truly different than this Horde, show us! Help us protect our grove by killing those who defile the land.", sourceObjective = "Kill 12 Twinspire Taskmasters or Twinspire Peons.", progress = "It is easier to harbor hatred than to make peace.", completion = "Our orchard is one of our village's greatest treasures. For saving our harvest, we are truly grateful.", sourceObjectiveStatus = "unverified-source-field" }
quests[31739] = { id = 31739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities!", description = "Those \"orc\" things ransacked the brewery and made off with my family's finest barrels of cider.\n\nI know there is a war out there, but I am not a brewer who will stand idly by while his prized vintage is chugged by undeserving lips.\n\nThe \"Horde\" will likely put up some resistance. Why don't you put that weapon to good use and help me recover my cider?", sourceObjective = "Collect 6 Applebloom Cider.", progress = "Is that my husband with you? Did you recover the cider?", completion = "I see that you two have been busy. Thank you for recovering our kegs.", sourceObjectiveStatus = "unverified-source-field" }
quests[31740] = { id = 31740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koukou's Rampage", description = "We have more than just our cellars to worry about.\n\nKoukou, our beloved mushan, has gone crazy! Just look at him!\n\nI've tried cajoling and pleading and yelling and soothing, but nothing has worked.\n\nI'm afraid he is no longer of his own mind. There is only one way to save him, and our brewery.\n\nStrike swift and sure. He will not feel a thing.", sourceObjective = "Kill Koukou.", completion = "You did well to help the Brewers and bring this news to me.\n\nFrom what you have told me, it sounds as if Koukou was possessed by some dark energy. Could it be...?\n\nNo. That is impossible.", sourceObjectiveStatus = "unverified-source-field" }
quests[31741] = { id = 31741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twinspire Keep", description = "I do not trust this Horde. They wield foul magic, and their intentions are clearly malevolent. We can no longer stand their presence in Twinspire Keep, so close to Paw'don.\n\nI beg you, visitor: thin their numbers before they do something awful to this village.", sourceObjective = "Slay 15 Horde troops in Twinspire Keep.", progress = "Gol' dang, but there's a bunch of 'em down there...", completion = "One heck of a bloody mess y'made down there, kid.\n\nNice work.", sourceObjectiveStatus = "unverified-source-field" }
quests[31742] = { id = 31742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fractured Forces", description = "The Horde have made our jobs easier for us. Their infighting and segregation have split their camp in two: orcs in the west, and undead in the east.\n\nThe orcs obey their commander Dalgan, while the undead follow Bellandra Felstorm, a powerful warlock. Hopefully, their internal squabbles will be enough of a distraction that you'll be able to sneak in there and kill both of them. Sully has already infiltrated the ruins; find him inside when you are done.", sourceObjective = "Slay Dalgan and Bellandra Felstorm.", progress = "Pretty scary-lookin' characters around here...", completion = "That's some fine and fancy killin', {class}.\n\nNow, with those two all done 'n' taken care of, all that's left is the big fella in the hall behind me.", sourceObjectiveStatus = "unverified-source-field" }
quests[31743] = { id = 31743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke Before Fire", description = "Sully scouted the Horde establishment to the north, and he reports seeing a large pile of explosives, along with a small force of demolishers. That's not to mention the demons that their warlocks have summoned.\n\nLuckily, we came prepared. We've got air support from the Skyfire. We just need to show our pilots where to strike.\n\n<Rell hands you a smoke flare, and gives you a knowing nod.>", sourceObjective = "Use the Alliance Flare to call in an airstrike on the Pile of Munitions, the Twinspire Demolishers, the Wild Imps, and Xhu'daggab.", progress = "What's that you've got, lad? Some kind o' flare?\n\nShoot, I coulda put together a better flare'n that in half a wink, if Rell had only asked.", completion = "Me lads up in the sky bring the heat, don't they? Ha ha ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[31744] = { id = 31744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfair Trade", description = "Though we have only just met, we have a common enemy: this group called the \"Horde.\"\n\nSeveral days ago, their leader made us a trade offer. When we refused, his servants abducted several of our cubs as bargaining chips.\n\nWe have called in the Shado-Pan to help, but they are in Kun-Lai Summit, a journey of several days. Can you come to our aid?", sourceObjective = "Free 8 Captive Pandaren Cubs from Twinspire Keep by slaying the demonic eyeballs that watch over them.", completion = "Aye, I seen the wee ones, too. Busted a few out on m'way up here.\n\nYe've done good, lad. Those cubs might have some nasty nightmares, but they'll grow up some day, thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31745] = { id = 31745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward and Inward", description = "\"Sha\" energy, hm? Tread carefully, {name} - there's a hidden darkness to this continent.\n\nWe'll stay behind to mop up the rest of the Horde, but we need you to continue with the main mission: the rescue of Captain Taylor, and the retrieval of Prince Anduin.\n\nOur aerial scouts think we've found the wreckage of the flagship near Paw'don Village. Go there and report to Admiral Rogers for instructions.\n\nYou are welcome to use my gyrocopter.", sourceObjective = "Report to Admiral Rogers at Paw'don Village in the Jade Forest.", completion = "Excellent work, {class}. I can see why you came so highly recommended.", sourceObjectiveStatus = "unverified-source-field" }
quests[31752] = { id = 31752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 4000", sourceObjective = "I am pleased to offer this gift to you, {race} {class}.  According to my calibrations, it will invoke feelings of enjoyment and gratitude.\n\nHave a nice day.", sourceObjectiveStatus = "unverified-source-field" }
quests[31754] = { id = 31754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannonfire", description = "Those mogu cannons up on the Golden Stair are bombarding us from a distance. Sure would be nice if they somehow spontaneously broke, don't you think?", sourceObjective = "Destroy 7 Shao-Tien Cannons.", progress = "Oh my pounding head! So loud, so obnoxious, these cannons firing all through the night...\n\nThese mogu really aren't a very considerate bunching.", completion = "It's a bit more quiet out now. My ringing ears appreciate your hard work.\n\nThanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[31755] = { id = 31755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acts of Cruelty", description = "I can hear the screams of the captured soldiers and villagers up on the Golden Stair. They're torturing them!\n\nPlease, please, you have to save them!", sourceObjective = "Rescue 5 Golden Lotus Guards or Mistfall Villagers.", progress = "No one deserved the agony the mogu bring upon us...", completion = "My heart rests a little easier knowing what you've done. Thank you, my dear.", sourceObjectiveStatus = "unverified-source-field" }
quests[31756] = { id = 31756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Chance of Rain", description = "The mogu are conjuring some kind of sinister storm upon the Golden Stair. Generally, mogu and lightning are not a particularly pleasant mix. I say we stop them.\n\nYou should be able to find their Stormcaller staves pretty easily, considering the giant arcs of lightning extending up from them. Mind knocking them over or destroying them or something for me? I sure would sleep better.", sourceObjective = "Destroy the Stormcaller staves.", progress = "If they were rice farmers, they could make a killing with rain on demand. These mogu really are reaching for the wrong calling in life.", completion = "It's a lot brighter out! And not just thanks to your sunny smile.\n\nWay to go!", sourceObjectiveStatus = "unverified-source-field" }
quests[31757] = { id = 31757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashed Spirits", description = "The Shao-Tien have unleashed their captive tortured spirits upon us. They flood down from the Golden Stair, with no end in sight.\n\nKill as many of these unleashed spirits as you can. They are fragile, but if you are not alert, they can easily overrun you.\n\nGood luck.", sourceObjective = "Kill 12 Unleashed Spirits.", completion = "The spirits still come, but our guards can hold them back. The Shao-Tien cannot keep this up for ever.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31758] = { id = 31758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laosy Scouting", description = "Lao Softfoot got himself captured again up on the Golden Stair. I'm not going to make any excuses for him, he's a lousy rogue.\n\nWe probably shouldn't just leave him there though. Could you go find him?", sourceObjective = "Rescue Lao Softfoot.", progress = "Lao needs to take a lesson from his brother, He. When you're sneaking around a hostile mogu camp, being a loudmouth isn't an asset.\n\nNot that it ever is, I guess.", completion = "You're a good man, helping that silly rogue out more than he deserves.", sourceObjectiveStatus = "unverified-source-field" }
quests[31760] = { id = 31760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Striking First", description = "The mogu are empowering some giant stone monstrosity up on the Golden Stair, with the sure intent of unleashing it upon us.\n\nHow about you go and let them know our opinion on the matter? Make sure the point strikes home.", sourceObjective = "Stop the Shao-Tien Behemoth from being empowered.", progress = "Go, go, share our diplomacy with the Shao-Tien.", completion = "How went the diplomacy? I hope you didn't go easy on them.", sourceObjectiveStatus = "unverified-source-field" }
quests[31762] = { id = 31762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crumbling Behemoth", description = "The mogu have succeeded in empowering an enormous stone statue with the intent of unleashing it upon us.\n\nIn response, I would like to unleash you upon it.\n\nIt approaches from the Golden Stair. Bring it to its knees...", sourceObjective = "Destroy the Shao-Tien Behomoth.", progress = "The sounds of battle get my blood pumping...", completion = "Glorious.  They will learn to fear us.", sourceObjectiveStatus = "unverified-source-field" }
quests[31765] = { id = 31765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Red!", description = "They shot out our engines and we floated here - HERE! Right in the firing line of the enemy!\n\nYou know what to do, {name}. Get below decks and man those guns!\n\nShow these scum that they're in OUR line of fire!", sourceObjective = "Use a Gunship Turret to kill 80 Thunder Hold troops and destroy 9 Thunder Hold cannons.", progress = "What are you waiting for?! Get on those guns!", completion = "Superior Horde firepower at its finest!\n\n...and you did okay too I guess.", sourceObjectiveStatus = "unverified-source-field" }
quests[31766] = { id = 31766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touching Ground", description = "Nazgrim has taken command of the ground assault and has requested that you be sent to meet up with him immediately.\n\nWe have several rappelling ropes setup near the guns. Fastest way down you're going to find, save the one that ends poorly.", sourceObjective = "Use a Rappelling Rope to reach the ground.", progress = "What?", completion = "There you are!\n\nI was starting to worry we'd have to charge in and have all the fun without you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31767] = { id = 31767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish Them!", description = "We've softened them up. Now it's time to finish them off!\n\nThat fortress must be cleansed of Alliance, and we've got nowhere to keep any prisoners.\n\n<The hint of a smile crosses Nazgrim's face.>\n\nYou know what to do, {name}. The cowards will run if you give them the chance.\n\nSee that you don't!", sourceObjective = "Slay 15 Thunder Hold troops.", completion = "Good work, {class}! We have them on their heels!", sourceObjectiveStatus = "unverified-source-field" }
quests[31768] = { id = 31768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Is Always the Answer", description = "It's not enough that we destroy their forces. Nothing must be left for them to salvage!\n\nTake this flare-gun and fire it into their munitions stockpiles. Leave them nothing!", sourceObjective = "Destroy 10 Stacks of Thunder Hold Munitions.", progress = "Burn them out!", completion = "Haha! Good work, {name}.\n\nLeave 'em nothing!", sourceObjectiveStatus = "unverified-source-field" }
quests[31769] = { id = 31769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Blow!", description = "We've learned that their captain has barricaded himself in above us.\n\nThe coward allowed his forces to die while he hid from our fury! Typical Alliance! No matter. He cannot delay his fate any longer.\n\nI will scale the walls with my marines while you lead a frontal assault up the ramps. Use your flare gun on munitions near the barricades to blast your way through.\n\nWe will meet you up top and destroy this pathetic excuse for a captain together!", sourceObjective = "Slay Captain Doren in Thunder Hold.", completion = "An air base - they had a hidden airbase here this entire time! Had I known I would've kept more men on the guns, I would've - Uaaghh -\n\n<The color drains from Nazgrim's face, and his body begins to exude a mysterious dark energy.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31770] = { id = 31770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Either With Us Or...", sourceObjective = "Attempt to enlist the help of Mayor Honeydew in Honeydew Village.", progress = "You seek the help of the village your war has just devastated? Interesting...", completion = "Your fighting has brought about much destruction for our tiny village!\n\nWe have no interest in your war, but we will not turn your injured away.", sourceObjectiveStatus = "unverified-source-field" }
quests[31771] = { id = 31771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Face to Face With Consequence", description = "I do not know the history of this war that you fight, and I am not interested. This land responds to negative energy in kind. The hatreds, doubt, and violence you have brought here now ooze out of Pandaria like blood from an open wound.\n\nYour actions have wrought havoc all over these ruins! Clean up after yourself and meet me in the village below - I will do my best to explain what is happening here.", sourceObjective = "Kill 20 Sha Haunts and 7 Sha Harbingers.", completion = "I am glad you took responsibility for your actions. Left unchecked, negative emotions can quickly overwhelm an individual here, just as they started to overwhelm the one you call \"Nazgrim.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[31772] = { id = 31772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorities!", description = "Just look at this mess! All that brew gone to waste!\n\nTaran Zhu warned us against speaking to you outsiders, but I'll take any help I can get.\n\nWe were on our way to Dawn's Blossom when the fighting broke out. Now all of our brew has been lost!\n\nYou want to make it up to us? Maybe you can find some of our Honeybrew barrels that haven't been broken. Then it wouldn't be a complete loss.", sourceObjective = "Find 6 Barrels of Honeybrew in Honeydew Glade.", completion = "Well, it's not as much as I would have hoped, but it will have to do. I guess there is no sense in cryin' over spilled brew.", sourceObjectiveStatus = "unverified-source-field" }
quests[31773] = { id = 31773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prowler Problems", description = "The animals have all gone crazy!\n\nNormally the prowlers steer clear of the village, but now we can't seem to keep them away. I've never seen them act this way before!\n\nThe mayor has summoned in the Shado-Pan, but they're not all here yet. Can you take care of those prowlers before they maul one of our farmers?", sourceObjective = "Destroy 10 Sha-Infested Prowlers in Honeydew Glade.", progress = "Look at this mess! This is madness!", completion = "Ah, so your conflict at the ruins is beginning to pollute the local wildlife? This is very troubling - I have never seen a reaction so intense.\n\nThank you for protecting the village, but it is a tragedy that those poor animals had to die.", sourceObjectiveStatus = "unverified-source-field" }
quests[31774] = { id = 31774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Zin'jun", description = "Rivett claims to have seen Zin'jun abandon ship with the rest of the survivors. That means he's still out there somewhere.\n\nWe can't leave him behind. He could be injured or worse yet, captured!\n\nGo track down Zin'jun and bring him back.", sourceObjective = "Locate Zin'jun somewhere in the Ascent of the Swirling Winds.", completion = "<Zin'Jun is grievously wounded, but senses that you're friendly.>\n\nMonkey-tings! Everywhere dere be dese monkey-tings!", sourceObjectiveStatus = "unverified-source-field" }
quests[31775] = { id = 31775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Airstrip", description = "I have found their hidden airfield, {name}: the Strongarm Airstrip. It wasn't hard to spot, it's swarming with Alliance.\n\n<Nazgrim spits.>\n\nThey think they've wiped us out, but we're Horde! We fight until we're corpses... and sometimes even afterwards. Let them taste our steel!", sourceObjective = "Slay 15 Strongarm troops at Strongarm Airstrip.", completion = "The best thing about killing Alliance in Pandaria? It'll be months before they get any reinforcements.\n\nThis land will belong to the Horde, {class}. We're nearly finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[31776] = { id = 31776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strongarm Tactics", description = "Scouting reports from the Strongarm Airstrip are in, and I've underlined a few high-priority targets for you.\n\nTwo gnomish mechanics have been keeping Alliance gyrocopters in the air. Take out the mechanics, and the gyrocopters' numbers will dwindle.\n\nA dwarven death knight wanders their perimeter. He's an adventurer like yourself - loosely allied and highly dangerous.\n\nFinally, a name I recognize: Corporal Jackson Silver. He's a hero of the Alliance and a deadshot with a crossbow.\n\nGood luck, {name}.", sourceObjective = "Slay Corporal Jackson Silver, Morgus Grimhatchet, and Master Mechanic Cogswing and Gyro-Engineer Lavenderp.", progress = "These aren't your normal kill targets, {name}. Be on guard.", completion = "Blood and thunder, {name}. Blood and thunder.", sourceObjectiveStatus = "unverified-source-field" }
quests[31777] = { id = 31777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choppertunity", description = "I spotted some shoulder-mounted rocket launchers on the way over here.\n\nThey mighta been fireworks. I dunno. I'm just going to assume that they were shoulder-mounted rocket launchers until I'm proven wrong.\n\nPoint is, in the arms of a skilled {class} like you, they could probably take down a chopper. If you find any lying around, try pointing them at those poorly-built gyrocopters.", sourceObjective = "Pick up Requisitioned Fireworks Launchers in Strongarm Airstrip, then use them on 12 Strongarm Gyrocopters.", progress = "Any luck?", completion = "I hope those ding-dongs enjoyed the party you threw for them!", sourceObjectiveStatus = "unverified-source-field" }
quests[31778] = { id = 31778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unreliable Allies", description = "We originally welcomed the Alliance as friends. Several of our villagers volunteered to help them build an airstrip. Only recently, however, did it become clear to us that they were building a war base, within shouting distance of our village.\n\nWhat's worse - I fear that some villagers are being held against their will. If you find them, {class}, let them know that it is time to come home.", sourceObjective = "Encourage 12 Pandaren Volunteers to leave the Strongarm Airstrip.", completion = "Although I can't understand why you chose to bring your war to our land, I can clearly see which side is more virtuous.\n\nThank you for your aid, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31779] = { id = 31779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Within", description = "You didn't see Captain Doren while you were out there, did you?\n\nThat sniveling Alliance leader must be in hiding somewhere. If he wasn't in that airbase, he can't be far. Search the perimeter - try searching the cave southwest of the main airfield. I want the Alliance gone from here!", sourceObjective = "Slay Captain Doren.", progress = "On your way then, {name}.", completion = "The Alliance have been routed. You, Nazgrim, Kiryn, Gorrok, Shokia, and Rivett need a base of operations.\n\nThese flags will have to be changed.\n\nFor the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[31781] = { id = 31781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay", description = "Think you can take me again?  I'm always up for challenge!", sourceObjective = "Defeat Lindsay in a pet battle.", completion = "That wasn't fun at all!", sourceObjectiveStatus = "unverified-source-field" }
quests[31782] = { id = 31782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overthrone", description = "The council is in harmony, wakener.\n\nOur ritual will bring about the demise of the empress and allow us to secure the future of our great empire.\n\nBehold the power of the Klaxxi!", sourceObjective = "Speak to Klaxxi'va Vor in Klaxxi'vess.", completion = "We are... undone, wakener.\n\nYour efforts appear to have become imperative to our cause.\n\nOn behalf of the remaining council, I implore you to continue in your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[31784] = { id = 31784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyx To Goodness", progress = "What do you have there, {name}?", completion = "You did well to bring this egg to me. We will take good care of it, {name}." }
quests[31785] = { id = 31785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level Up!", description = "Good, good. It's important to keep your pets healthy and ready for battle.\n\nMy next task for you is to fight a few battles and raise a pet to level 3.  Once you do that, come back and see me and we can talk about catching your own pets!", sourceObjective = "Raise a pet to level 3.", completion = "Great job {name}.  Next up, catching your own pets!", sourceObjectiveStatus = "unverified-source-field" }
quests[31786] = { id = 31786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Manacles of Rebellion", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", sourceObjective = "Put the artifact on display.", progress = "Remove the clutter and put the artifact on display.", completion = "This will aid lorewalkers and archaeologists in understanding the history of Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
