quests[31808] = { id = 31808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampage Against the Machine", description = "Kovok has progressed at an astonishing rate. Perhaps the years in hibernation effected his growth process...\n\nWhatever the reason, this could not have come at a better time. I believe it is time to test his abilities.\n\nYou have done so much to aid in his training. It is only fitting that you assist him in his first battle.\n\nI've already guided him to the edge of the scar. Find him and destroy Shek'zeer's army!", sourceObjective = "Kill 200 Mantid while controlling Kovok in the Scar.", progress = "Was the battle glorious?! How many of Shekzeer's army fell to Kovok?", completion = "I was able to glimpse moments of the battle through your mind. It looked to be a massacre! Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[31809] = { id = 31809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of Anger", description = "As you look upon the severed claw of the defeated Sha of Anger, you realize that Ban Bearheart, commander of the Shado-Pan in Townlong Steppes, would want to know of your victory.", sourceObjective = "Deliver the Claw of Anger to Ban Bearheart at the Shado-Pan Garrison in Townlong Steppes.", progress = "<Ban looks at you with narrowed eyes.>\n\nSomething about you is... different. Changed.", completion = "<As you present the Claw to Ban, his eyes grow wide with the realization of what you have done.>\n\nI see now what about you has changed.\n\nYou have done the impossible. The Shado-Pan shall record your name, and honor it as long as we stand watch over this land.", sourceObjectiveStatus = "unverified-source-field" }
quests[31810] = { id = 31810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", sourceObjective = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!", sourceObjectiveStatus = "unverified-source-field" }
quests[31811] = { id = 31811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Skies", description = "I can no longer call myself your teacher, {name}.\n\nYou have proven yourself worthy of your cloud serpent.\n\nToday, you shall join our ranks. Are you ready?", sourceObjective = "Join the Order of the Cloud Serpent.", completion = "Today, we become brethren. Congratulations on joining the Order of the Cloud Serpent. Let us ride together!", sourceObjectiveStatus = "unverified-source-field" }
quests[31812] = { id = 31812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zunta, The Pet Tamer", description = "I can tell you have been honing your pet battle skills, {name}.  I think it's time for you to take on a real challenge.\n\nZunta can be found near the Tor'kren Farm south of Orgrimmar.  He is an up and coming wild pet tamer and I think it's time you faced him in battle!", sourceObjective = "Defeat Zunta in a pet battle.", progress = "Who be sendin' you to face Zunta?", completion = "Ah, Varzok. Yes, I know him well. He be makin' no mistake in sendin' you here.", sourceObjectiveStatus = "unverified-source-field" }
quests[31813] = { id = 31813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagra the Fierce", description = "Der be another trainer not far from here that you ought to fight to test your worth.\n\nDagra the Fierce waits on the northern slope of Thorn Hill, east of The Crossroads. If you be beatin' her, you just might have what it takes.", sourceObjective = "Defeat Dagra the Fierce in a pet battle.", progress = "I fear nothing. I will not be defeated!", completion = "You fight with the determination of one who does not fear defeat, but does not tolerate it, either. You will go far.", sourceObjectiveStatus = "unverified-source-field" }
quests[31814] = { id = 31814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Analynn", description = "Determination is naught without proper challenge.\n\nFind Analynn wandering the roads in western Ashenvale. She is a bit...eccentric...but a fine trainer nonetheless! Fighting her will harden your team.", sourceObjective = "Defeat Analynn in a pet battle.", progress = "You're a curious sort.", completion = "You do not understand. I have not been defeated, merely set back.", sourceObjectiveStatus = "unverified-source-field" }
quests[31815] = { id = 31815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zonya the Sadist", description = "{name}, a rare opportunity has arisen that I think you will be interested in.\n\nZonya the Sadist in southern Stonetalon Mountains has returned to the battle scene. I must suggest that you face her to further hone your own abilities as a tamer.", sourceObjective = "Defeat Zonya the Sadist in a pet battle.", progress = "You be messin' with da wrong {race}, mon.", completion = "Did you enjoy the taste of victory? It'll be your last, mon. Things do not get easier from here.", sourceObjectiveStatus = "unverified-source-field" }
quests[31816] = { id = 31816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor Gluk", description = "Are you up for an adventure? Bill the Pirate, local star tamer down in the Cape of Stranglethorn, has issued an open challenge to prepared trainers!\n\nYou can find Bill the Pirate in the southern Cape of Stranglethorn, walking the local roads to find potential fights.", sourceObjective = "Defeat Bill the Pirate in a pet battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[31817] = { id = 31817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merda Stronghoof", description = "Are you ready for a real measure of your prowess, {race}?\n\nMerda Stronghoof has made camp at da place dey call Karnum's Glade in the Cenarion Wildlands of Desolace. Fighting a trainer as powerful as her will put your skills to the test, eh?", sourceObjective = "Defeat Merda Stronghoof in a pet battle.", progress = "You think yourself stronger than the very earth you walk upon?", completion = "The resilience of Desolace cannot compare to your own desire to grow. I applaud your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[31818] = { id = 31818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zunta", description = "Think you can take me again, eh?", sourceObjective = "Defeat Zunta in a pet battle.", completion = "Lay off, mon! Lay off! You win!", sourceObjectiveStatus = "unverified-source-field" }
quests[31819] = { id = 31819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dagra the Fierce", description = "You climbed this mountain once more only to face your own demise.", sourceObjective = "Defeat Dagra the Fierce in a pet battle.", completion = "Impossible!", sourceObjectiveStatus = "unverified-source-field" }
quests[31820] = { id = 31820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Present for Teacher", description = "I'm all caught up with the other kids now, even though I started very late. Now I can join the regular classes!\n\nI made you an apron to show you how much I appreciate all you've done for me. I hope you like it?", sourceObjective = "Receive Nomi's gift.", completion = "Thank you so much.", sourceObjectiveStatus = "unverified-source-field" }
quests[31821] = { id = 31821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level Up!", description = "Good, good. It's important to keep your pets healthy and ready for battle.\n\nMy next task for you is to fight a few battles and raise a pet to level 3.  Once you do that, come back and see me and we can talk about catching your own pets!", sourceObjective = "Raise a pet to level 3.", completion = "Great job {name}.  Next up, catching your own pets!", sourceObjectiveStatus = "unverified-source-field" }
