quests[31833] = { id = 31833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue Your Training: Master Woo", description = "Welcome back {name}, the time has come for the next step of your training.  Speak with Master Woo in the Training Grounds below us for your next lesson.", sourceObjective = "Speak with Master Woo in the Peak of Serenity and complete your training with her.", progress = "Complete your training with Master Woo.", completion = "I hear from Master Woo that your training went well.  Come back again in the future to continue your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[31834] = { id = 31834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begin Your Training: Master Cheng", description = "Greetings, {name}. Welcome to the Peak of Serenity.  It is here that we monks train and hone our skills in the martial arts.  The time has come for you to begin your training.  Speak with Master Cheng in the Training Grounds below us to begin.", sourceObjective = "Speak with Master Cheng in the Training Grounds and complete your training with him.", progress = "Complete your training with Master Cheng.", completion = "I hear from Master Cheng that your training went well.  Come back again in the future to continue your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[31835] = { id = 31835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue Your Training: Master Kistane", description = "Welcome back {name}, the time has come for the next step of your training.  Speak with Master Kistane in the Training Grounds below us for your next lesson.", sourceObjective = "Speak with Master Kistane in the Peak of Serenity and complete your training with her.", progress = "Complete your training with Master Kistane.", completion = "I hear from Master Kistane that your training went well.  Come back again in the future to continue your training.", sourceObjectiveStatus = "unverified-source-field" }
