quests[31847] = { id = 31847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Dead than Dread", description = "I am sure many of our associates will be requesting your services after your victory here. But I have received a request for aid from our defenders at the wall along the Dread Wastes.\n\nIf you would assist them, then take a kite and check in with Bowmistress Li.", sourceObjective = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31850] = { id = 31850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eric Davidson", description = "Ah, so you've braved the woods again to face me in battle. I accept your brazen challenge to my vicious spawn.", sourceObjective = "Defeat Eric Davidson in a pet battle.", completion = "Your risk has paid its reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[31851] = { id = 31851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bill Buckler", description = "So ye've come fer another round, have ye?\n\nI'll show ya why they be callin' me the shcourge o' the vale!", sourceObjective = "Defeat Bill Buckler in a pet battle.", completion = "You be the victor today, lad, but next time I won't be takin' it so eashy on ye!", sourceObjectiveStatus = "unverified-source-field" }
quests[31852] = { id = 31852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steven Lisbane", description = "You dare to challenge me again? This time, I do believe our battle is going to sway in my favor!", sourceObjective = "Defeat Steven Lisbane in a pet battle.", completion = "A thrilling match! Splendid! Well done indeed!", sourceObjectiveStatus = "unverified-source-field" }
quests[31853] = { id = 31853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Aboard!", description = "You hear all of that, {name}? There are Alliance that need killing and I need to round up a veteran crew.\n\nYou're coming with me!\n\nWe won't be returning until our assignment's complete, so round up your things and make ready.\n\nI'll be aboard a newly commissioned gunship over Bladefist Bay.\n\nDon't keep me waiting!", sourceObjective = "Speak to General Nazgrim aboard Hellscream's Fist.", completion = "Welcome aboard Hellscream's Fist, {name}!\n\nThis'll be her maiden voyage. Ain't she a beauty?", sourceObjectiveStatus = "unverified-source-field" }
quests[31854] = { id = 31854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Analynn", description = "I see you have once again found me. I presume you wish to do battle once more? Yes, let's.", sourceObjective = "Defeat Analynn in a pet battle.", completion = "Your pets are ecstatic about their victory. I hope you are as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[31855] = { id = 31855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Serenity - Continue Your Training", description = "The time has come for you to return to the Peak of Serenity to continue your training.  Use Zen Pilgrimage to return there and speak with Master Hight when you arrive.", sourceObjective = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome back, {name}.  It is time to continue your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[31856] = { id = 31856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Peak of Serenity - Begin Your Training", description = "The time has come for you to venture to the Peak of Serenity to begin training in the ways of the Monk.  Use Zen Pilgrimage to go there and speak with Master Hight when you arrive.", sourceObjective = "Use Zen Pilgrimage to travel to the Peak of Serenity. Speak to Master Hight in the Shrine of the Ox when you arrive.", completion = "Welcome, {name}.  It is time to begin your training.", sourceObjectiveStatus = "unverified-source-field" }
