quests[31862] = { id = 31862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zonya the Sadist", description = "The prey be walkin' to the predator's territory, unaware of the danger that <he/she> is in. You be givin' Zonya no trouble dis time.", sourceObjective = "Defeat Zonya the Sadist in a pet battle.", completion = "You think yourself victorious, but I be growin' stronger with each defeat.", sourceObjectiveStatus = "unverified-source-field" }
quests[31870] = { id = 31870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cassandra Kaboom", description = "Cassandra Kaboom is a fierce tamer, known for her mechanical pets. She should serve as the next step on your journey to greatness.\n\nFind her in Southern Barrens near the Frazzlecraz Motherlode and challenge her. Beating Cassandra will surely prove yourself in the eyes of Varzok.\n\nGood luck.", sourceObjective = "Defeat Cassandra Kaboom in a pet battle.", progress = "What's a {race} like you doin' in a place like this?", completion = "Woah! You really are somethin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[31871] = { id = 31871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitor Gluk", description = "You beat Gluk before, but now Gluk lay da smackdown on puny {race}!", sourceObjective = "Defeat Traitor Gluk in a pet battle.", completion = "No! Gluk no lose! Rematch!", sourceObjectiveStatus = "unverified-source-field" }
quests[31872] = { id = 31872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merda Stronghoof", description = "Just as the land continues to grow, my team is stronger than ever. Are you sure you wish to combat me? There is no shame in admitting defeat now.", sourceObjective = "Defeat Merda Stronghoof in a pet battle.", completion = "Your victory is well-deserved. Your skills are superior to my own.", sourceObjectiveStatus = "unverified-source-field" }
quests[31876] = { id = 31876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", sourceObjective = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.", completion = "Ah, a scribe of great skill. Some of us here could really use your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[31877] = { id = 31877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inkmasters of the Arboretum", description = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill.  You should speak with Inkmaster Wei, if you wish to help.", sourceObjective = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[31878] = { id = 31878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audrey Burnhep", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n{race}eport to Audrey Burnhep in Stormwind. She has connections with many of Azeroth's finest trainers, and will help you grow further.", sourceObjective = "Report to Audrey Burnhep in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
