quests[31882] = { id = 31882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Varzok in Orgrimmar. He has connections with many of Azeroth's finest trainers, and will help you grow further.", sourceObjective = "Report to Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31883] = { id = 31883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Varzok in Orgrimmar. He has connections with many of Azeroth's finest trainers, and will help you grow further.", sourceObjective = "Report to Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
