quests[31885] = { id = 31885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Varzok", description = "I'm afraid I have nothing left to teach you, {name}. However, your journey as a trainer is far from over!\n\nReport to Varzok in Orgrimmar. He has connections with many of Azeroth's finest trainers, and will help you grow further.", sourceObjective = "Report to Varzok in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[31886] = { id = 31886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", sourceObjective = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31887] = { id = 31887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Trainers: Kalimdor", description = "It's time to put your battle skills to a true test.\n\nYou will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!", sourceObjective = "Defeat Steven Lisbane in a pet battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[31889] = { id = 31889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", sourceObjective = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31891] = { id = 31891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Kalimdor", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade.\n\nIf you are able to best them, you will be ready to venture further.", sourceObjective = "Defeat Traitor Gluk, Grazzle the Great, Kela Grimtotem, Zoltan, and Elena Flutterfly in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31892] = { id = 31892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Trainers: Kalimdor", description = "The very same trainers you bested before in Kalimdor have challenged you once more. No doubt they have not forgotten your last victory!\n\nSeek them out and show them your prowess!", sourceObjective = "Defeat Elena Flutterfly, Cassandra Kaboom, Golbo the Great, Zoltan, and Kela Grimtotem in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31894] = { id = 31894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delicate Balance", description = "The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, {name}.\n\nThe yaungol activity in Townlong is threatening this balance and must be stopped before it is too late.\n\nWe've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it!", sourceObjective = "Speak with Orbiss in the Sumprushes.", completion = "<Orbiss groans at you in agony.>\n\nSo, the shado-pan have sent you to see what the yaungol are doing? Well, do you see?", sourceObjectiveStatus = "unverified-source-field" }
quests[31895] = { id = 31895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Off Dread", description = "It's time we go to the source, {name}!\n\nShado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nSeek out Bowmistress Li atop the Serpent's Spine on the border of Dread Wastes.", sourceObjective = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31897] = { id = 31897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Trixxy", description = "Word around the master tamers in Kalimdor is you're the new hotshot that's making such a buzz. Why don't you come down to my training grounds in the Ice Thistle Hills in Winterspring so I can show you how it's done?", sourceObjective = "Defeat Stone Cold Trixxy in a pet battle.", progress = "You're tougher than you look!", completion = "You really are some sort of hotshot, aren't ya? You won't be so lucky next time!", sourceObjectiveStatus = "unverified-source-field" }
quests[31902] = { id = 31902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes.\n\nIf you are able to best them, you will be ready to venture further.", sourceObjective = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31903] = { id = 31903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Eastern Kingdoms", description = "Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full.\n\nThere are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer, in Burning Steppes..\n\nIf you are able to best them, you will be ready to venture further.", sourceObjective = "Defeat David Kosse, Deiza Plaguehorn, Kortas Darkhammer, Everessa, and Durin Darkhammer in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31904] = { id = 31904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cassandra Kaboom", description = "I've loaded my pets with new gyrotechnic training modules. You're going down!", sourceObjective = "Defeat Cassandra Kaboom in a pet battle.", completion = "I must've converted a line wrong somewhere...", sourceObjectiveStatus = "unverified-source-field" }
quests[31905] = { id = 31905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grazzle the Great", description = "You're back?! You're just asking to get eaten by a black dragon!", sourceObjective = "Defeat Grazzle the Great in a pet battle.", progress = "I've seen better.", completion = "It's like my pretties have lost their will to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[31906] = { id = 31906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kela Grimtotem", description = "You're so bold as to venture into the heart of Grimtotem lands once more to challenge me? You will regret your decision!", sourceObjective = "Defeat Kela Grimtotem in a pet battle.", completion = "Mark my words, I will defeat you one day soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[31907] = { id = 31907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoltan", description = "With each passing day my power grows. Resistance is futile.", sourceObjective = "Defeat Zoltan in a pet battle.", completion = "This world is doomed. Why do you continue to try so fervently?", sourceObjectiveStatus = "unverified-source-field" }
quests[31908] = { id = 31908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elena Flutterfly", description = "I see you're ready for another bout in the skies. Let's take flight!", sourceObjective = "Defeat Elena Flutterfly in a pet battle.", completion = "My flight has come to an end. Victory is yours this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[31909] = { id = 31909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Trixxy", description = "Freeze! You've finally warmed up from our last encounter, have you? Let's change that.", sourceObjective = "Defeat Stone Cold Trixxy in a pet battle.", progress = "You show no mercy. I like you.", completion = "You're hot stuff!", sourceObjectiveStatus = "unverified-source-field" }
quests[31910] = { id = 31910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "David Kosse", description = "My research has helped my training regimen greatly. I will defeat you this time.", sourceObjective = "Defeat David Kosse in a pet battle.", completion = "Perhaps my research is not as complete as I thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[31911] = { id = 31911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deiza Plaguehorn", description = "You have not yet turned to the true path of undeath. Perhaps another battle will show you the way.", sourceObjective = "Defeat Deiza Plaguehorn in a pet battle.", completion = "Perhaps undeath is not the answer...", sourceObjectiveStatus = "unverified-source-field" }
quests[31912] = { id = 31912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kortas Darkhammer", description = "I hear that you fought my fool of a brother. He lost, eh?\n\nLooks like this is my time to shine!", sourceObjective = "Defeat Kortas Darkhammer in a pet battle.", progress = "How do you have such a strong team?", completion = "You're no better than Durin. In it for the glory. Pah!", sourceObjectiveStatus = "unverified-source-field" }
quests[31913] = { id = 31913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everessa", description = "I believe I'm figuring out the secrets of this place. Soon I will be unstoppable!", sourceObjective = "Defeat Everessa in a pet battle.", completion = "I see you have secrets of your own.", sourceObjectiveStatus = "unverified-source-field" }
quests[31914] = { id = 31914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durin Darkhammer", description = "My time under the Firelord has prepared me fer anything. Nothing you can throw at me will deter me!", sourceObjective = "Defeat Durin Darkhammer in a pet battle.", progress = "What realm spawned a fighter of your caliber?", completion = "I'll defeat ye if it's the last thing I ever do. I haven't come this far fer nothin'!", sourceObjectiveStatus = "unverified-source-field" }
quests[31915] = { id = 31915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Lydia Accoste", description = "The master tamers around the Eastern Kingdoms have been talking about you. You think yourself unstoppable? You believe that you are the true grand master?\n\nCome, then, {name}. I await you in Deadwind Pass. Come, and know the crushing defeat that's always been yours.", sourceObjective = "Defeat Lydia Accoste in a pet battle.", progress = "Your power is not like the others'...", completion = "I have an eternity to train. I will defeat you!", sourceObjectiveStatus = "unverified-source-field" }
quests[31916] = { id = 31916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Lydia Accoste", description = "You wish to face me again? You will regret this decision!", sourceObjective = "Defeat Lydia Accoste in a pet battle.", progress = "You are powerful beyond my own belief.", completion = "You continue to reveal your strategies to me. Eventually, your defeat will be certain.", sourceObjectiveStatus = "unverified-source-field" }
quests[31917] = { id = 31917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tamer's Homecoming", description = "Yer ready to enter the full circuit of pet battlin', matey. Go back to yer trainer, Mish Burnhep, in Stormwind, and prepare for the adventure of a lifetime!", sourceObjective = "Report to Audrey Burnhep in Stormwind.", completion = "I'm so proud of you, {name}. You're ready for the big time!", sourceObjectiveStatus = "unverified-source-field" }
quests[31918] = { id = 31918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tamer's Homecoming", description = "If you beat me, then you must be ready for da big time! Go talk to Varzok in Orgrimmar.", sourceObjective = "Report to Varzok in Orgrimmar.", completion = "Well done, {name}. You are finally prepared to truly come into your own as a tamer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31919] = { id = 31919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", sourceObjective = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31920] = { id = 31920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Master Antari", description = "I've seen the likes of you before. A young, naive tamer that thinks that they deserve victory handed to them on a silver platter.\n\nWell no more! I will be your reckoning, {class}. I, Bloodknight Antari of Shadowmoon Valley, await the chance to show you how it feels to be obliterated in battle.", sourceObjective = "Defeat Bloodknight Antari in a pet battle.", progress = "I don't believe it...", completion = "Impossible! I cannot lose!", sourceObjectiveStatus = "unverified-source-field" }
quests[31921] = { id = 31921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Pet Tamers: Outland", description = "You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying.\n\nThere are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath.\n\nYou must defeat them to proceed on the path to greatness.", sourceObjective = "Defeat Nicki Tinytech, Ras'an, Narrok, and Morulu the Elder in pet battles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31922] = { id = 31922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicki Tinytech", description = "According to my calculations, I have a 32.333% chance of victory. I'll take it!", sourceObjective = "Defeat Nicki Tinytech in a pet battle.", completion = "I forgot to carry the 1!", sourceObjectiveStatus = "unverified-source-field" }
quests[31923] = { id = 31923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ras'an", description = "You want to fight again? I think I've gotten better!", sourceObjective = "Defeat Ras'an in a pet battle.", completion = "Nice work!", sourceObjectiveStatus = "unverified-source-field" }
quests[31924] = { id = 31924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narrok", description = "I wish to do battle once more. These young ones need to grow stronger.", sourceObjective = "Defeat Narrok in a pet battle.", completion = "It would seem that these younglings still have a lot of work to do before they are at full strength. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31925] = { id = 31925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morulu The Elder", description = "I have learned much since our last encounter. Do you wish to test your skills once more?", sourceObjective = "Defeat Morulu The Elder in a pet battle.", progress = "You are truly wise beyond your years.", completion = "Even I continue to learn from each passing day.", sourceObjectiveStatus = "unverified-source-field" }
